   if(enemyInhibitor?.dead){const superM=makeMinion(lane,team,'melee');superM.super=true;superM.minionType='super';superM.hp=superM.maxHp=260*(1+(battleTier-1)*.18);superM.damage=24+(battleTier-1)*4;superM.r=20;superM.goldReward=35;superM.xpReward=42;minions.push(superM)}
