function evaluatePerformance(rating,win){const score=rating+(win?110:0)+(stats.deaths===0?70:0),grade=score>=950?'S+':score>=760?'S':score>=580?'A':score>=400?'B':score>=240?'C':'D',medals=[];if(stats.kills>=5)medals.push(['slayer','КАРАТЕЛЬ']);if(stats.assists>=6)medals.push(['team','КОМАНДНЫЙ ИГРОК']);if(stats.deaths===0&&stats.kills+stats.assists>=3)medals.push(['immortal','БЕССМЕРТНЫЙ']);if(stats.damage>=1400)medals.push(['damage','РАЗРУШИТЕЛЬ']);if(stats.damageTaken>=900)medals.push(['bulwark','ЖИВОЙ ЩИТ']);if(stats.healingDone>=350)medals.push(['healer','ЦЕЛИТЕЛЬ']);if(stats.towers>=2)medals.push(['siege','ОСАДНЫЙ МАСТЕР']);if(stats.monsters>=5)medals.push(['hunter','ВЛАДЫКА ЛЕСА']);if(stats.wards>=3)medals.push(['vision','ХРАНИТЕЛЬ ОБЗОРА']);if(stats.dodges>=5)medals.push(['dancer','ТАНЦУЮЩИЙ С БУРЕЙ']);if(stats.contracts>=2)medals.push(['contractor','ИСПОЛНИТЕЛЬ']);if(stats.riverRunes>=2)medals.push(['river','ВЛАДЫКА РЕКИ']);if(stats.rivalDefeats>=2)medals.push(['nemesis','УКРОТИТЕЛЬ СОПЕРНИКА']);if(roleAscended)medals.push(['role','МАСТЕР ПОЗИЦИИ']);return{score,grade,medals,mvp:grade==='S'||grade==='S+'}}
