function showCommendations(appraisal){const panel=document.querySelector('#commendation');panel.classList.remove('hidden');const allies=botHeroes.filter(b=>b.team==='blue'),received=appraisal.grade==='S+'?4:appraisal.grade==='S'?3:appraisal.grade==='A'?2:appraisal.grade==='B'?1:0;if(received){profile.commendations+=received;grantHonor(received*5,`получено похвал: ${received}`)}panel.innerHTML=`<b>ЧЕСТЬ КОМАНДЫ</b><small>${received?`Союзники похвалили вас: ${received}`:'Получайте похвалу за полезную игру'} · выберите одного союзника</small><div>${allies.map((b,i)=>`<button data-commend="${i}">${b.name||'СОЮЗНИК'}<em>${b.role||'КОМАНДА'}</em></button>`).join('')}</div>`;panel.querySelectorAll('[data-commend]').forEach(button=>button.onclick=()=>{if(commendationGiven)return;commendationGiven=true;button.classList.add('chosen');panel.querySelectorAll('button').forEach(b=>b.disabled=true);grantHonor(3,'похвала союзнику');grantSeasonXp(8);saveProfile();button.innerHTML+=' ✓';showToast('Похвала отправлена · честь +3')})}
